local R=dofile('tests/kernel_billboards_harness.lua')
local n=0
local function case(name,fn)R.menuCase(name,fn);n=n+1 end
case('root parent',function(r)r.menu.openBillboardsMenu();assert(r.last.menu=='forge_core_server_settings'and #r.last.options==4)end)
case('settings route',function(r)r.menu.openServerSettingsMenu();r.select(13);assert(r.last.id=='forge_core_billboards')end)
case('fetch denied',function(r)r.rpcHook=function()return false,'no_permission'end;r.menu.openBillboardsMenu()end)
case('fetch malformed',function(r)r.rpcHook=function()return true,false end;r.menu.openBillboardsMenu();assert(#r.billboards.entries==0)end)
case('fetch immediate runtime update',function(r)r.menu.openBillboardsMenu();assert(#r.billboards.entries==1)end)
case('create group cancel',function(r)r.menu.openBillboardsMenu();r.select(1)end)
case('create group save',function(r)r.inputs={{'New'}};r.menu.openBillboardsMenu();r.select(1);r.runTimers()end)
case('create group denied',function(r)r.inputs={{'New'}};r.menu.openBillboardsMenu();r.rpcHook=function()return false,'no_permission'end;r.select(1);r.runTimers()end)
case('group fallback and parent',function(r)r.menu.openBillboardsGroup(99,'Fallback');assert(r.last.title=='Fallback'and r.last.menu=='forge_core_billboards'and #r.last.options==4)end)
case('nonempty group count disabled',function(r)r.payload.groups[1].count=1;r.menu.openBillboardsGroup(1,'A');assert(r.last.options[3].disabled)end)
case('rename cancel',function(r)r.menu.openBillboardsGroup(1,'A');r.select(2)end)
case('rename save',function(r)r.inputs={{'New'}};r.menu.openBillboardsGroup(1,'A');r.select(2);r.runTimers()end)
case('rename denied',function(r)r.inputs={{'New'}};r.menu.openBillboardsGroup(1,'A');r.rpcHook=function()return false,'save_failed'end;r.select(2);r.runTimers()end)
case('delete group confirm',function(r)r.alerts={'confirm'};r.menu.openBillboardsGroup(2,'B');r.select(3);r.runTimers()end)
case('delete group cancel',function(r)r.alerts={'cancel'};r.menu.openBillboardsGroup(2,'B');r.select(3)end)
case('delete group denied',function(r)r.alerts={'confirm'};r.menu.openBillboardsGroup(2,'B');r.rpcHook=function()return false,'group_not_empty'end;r.select(3);r.runTimers()end)
case('missing board returns root',function(r)r.menu.openBillboardActions(99);assert(r.last.id=='forge_core_billboards')end)
case('actions parent',function(r)r.menu.openBillboardActions(1);assert(#r.last.options==5 and r.last.menu=='forge_core_billboards_group_1')end)
case('edit data cancel',function(r)r.menu.openBillboardActions(1);r.select(1)end)
case('edit data save dimensions/offset',function(r)r.inputHook=function(_,fields)assert(#fields==6 and fields[6].min==-2 and fields[6].max==2);return{'New','false','fixture://new',900,600,-0.1}end;r.menu.openBillboardActions(1);r.select(1);r.runTimers()end)
case('edit data denied',function(r)r.inputs={{'New','true','x',900,600,0}};r.menu.openBillboardActions(1);r.rpcHook=function()return false,'save_failed'end;r.select(1);r.runTimers()end)
case('create board capture confirm',function(r)r.inputs={{'New','true','fixture://new',900,600,0.1}};r.menu.openBillboardsGroup(1,'A');local co=r.run(function()r.select(1)end);R.completeCapture(r,co);r.runTimers()end)
case('create capture canceled',function(r)r.menu.openBillboardsGroup(1,'A');local co=r.run(function()r.select(1)end);r.just={[177]=true};r.resume(co)end)
case('create dialog canceled',function(r)r.menu.openBillboardsGroup(1,'A');local co=r.run(function()r.select(1)end);R.completeCapture(r,co);assert(r.last.id=='forge_core_billboards_group_1')end)
case('create board denied',function(r)r.inputs={{'New','true','x',900,600,0}};r.menu.openBillboardsGroup(1,'A');local co=r.run(function()r.select(1)end);r.rpcHook=function()return false,'no_permission'end;R.completeCapture(r,co);r.runTimers()end)
case('capture busy',function(r)r.menu.openBillboardsGroup(1,'A');r.billboards.captureActive=true;r.select(1)end)
case('capture unavailable',function(r)r.library.raycast=nil;r.menu.openBillboardsGroup(1,'A');r.select(1)end)
case('recapture confirm',function(r)r.menu.openBillboardActions(1);local co=r.run(function()r.select(2)end);R.completeCapture(r,co);r.runTimers()end)
case('recapture canceled',function(r)r.menu.openBillboardActions(1);local co=r.run(function()r.select(2)end);r.just={[202]=true};r.resume(co)end)
case('recapture unavailable',function(r)r.library.raycast=nil;r.menu.openBillboardActions(1);r.select(2)end)
case('recapture refused save',function(r)r.menu.openBillboardActions(1);local co=r.run(function()r.select(2)end);r.rpcHook=function()return false,'save_failed'end;R.completeCapture(r,co);r.runTimers()end)
case('fine tune confirm',function(r)r.menu.openBillboardActions(1);local co=r.run(function()r.select(3)end);r.controls={[172]=true};r.resume(co);r.finish(co);r.runTimers()end)
case('fine tune canceled',function(r)r.menu.openBillboardActions(1);local co=r.run(function()r.select(3)end);r.finish(co,false)end)
case('fine tune busy',function(r)r.menu.openBillboardActions(1);r.billboards.captureActive=true;r.select(3)end)
case('fine tune save refused',function(r)r.menu.openBillboardActions(1);local co=r.run(function()r.select(3)end);r.rpcHook=function()return false,'save_failed'end;r.finish(co);r.runTimers()end)
case('toggle optimistic off destroys texture',function(r)r.menu.openBillboardActions(1);r.tick();assert(r.duis[201]);r.select(4);assert(not r.duis[201]);r.runTimers()end)
case('toggle optimistic refusal no immediate rollback',function(r)r.menu.openBillboardActions(1);r.tick();r.rpcHook=function()return false,'no_permission'end;r.select(4);assert(not r.billboards.entries[1].enabled and not r.duis[201]);r.runTimers()end)
case('toggle on string false',function(r)r.payload.billboards[1].enabled='false';r.menu.openBillboardActions(1);r.select(4);r.runTimers()end)
case('toggle response applied even on refusal',function(r)r.menu.openBillboardActions(1);r.rpcHook=function()local p=setmetatable(R.seed(),{__tostring=function()return'fixture-response'end});p.enabled=false;return false,p end;r.select(4);assert(not r.billboards.enabled and #r.billboards.entries==0)end)
case('malformed response ignored',function(r)r.menu.openBillboardActions(1);r.rpcHook=function()return true,{billboards=false}end;r.select(4);assert(#r.billboards.entries==1)end)
case('delete board confirm',function(r)r.alerts={'confirm'};r.menu.openBillboardActions(1);r.select(5);r.runTimers()end)
case('delete board cancel',function(r)r.alerts={'cancel'};r.menu.openBillboardActions(1);r.select(5)end)
case('delete board refused',function(r)r.alerts={'confirm'};r.menu.openBillboardActions(1);r.rpcHook=function()return false,'save_failed'end;r.select(5);r.runTimers()end)
case('sort boards',function(r)r.payload.billboards[2]={id=5,groupId=1,name='Five'};r.payload.billboards[3]={id=2,groupId=1,name='Two'};r.menu.openBillboardsGroup(1,'A');assert(r.last.options[6].title=='[2] Two'and r.last.options[7].title=='[5] Five')end)
case('menu snapshot older than payload',function(r)r.menu.openBillboardActions(1);r.payload.billboards[1].name='Updated';r.select(4);r.runTimers()end)
case('RPC exception after optimistic toggle',function(r)r.menu.openBillboardActions(1);r.tick();r.rpcHook=function()error('fixture-rpc',0)end;assert(not pcall(r.select,4)and not r.duis[201]and not r.billboards.entries[1].enabled)end)
print('PASS billboards menu differentials '..n)
